rows=list(csv.DictReader(io.StringIO(DATA_CSV)))
for r in rows:
 for k in ['total_seconds','input_seconds','training_seconds','val2_ber']:r[k]=float(r[k])
 for k in ['val2_bit_errors','val2_bits','total_iteration']:r[k]=int(r[k])
 assert np.isclose(r['val2_ber'],r['val2_bit_errors']/r['val2_bits'],rtol=1e-13)
 assert np.isclose(r['total_seconds'],r['input_seconds']+r['training_seconds'],rtol=1e-13)
ref=next(r for r in rows if r['candidate']=='CNN')
ids=[f'd{d}_w{w}' for d in range(1,11) for w in [8,16,32,64]]
D={c:[r for r in rows if r['candidate']==c] for c in ids};assert all(D.values())
def score(r,a):return a*ref['val2_ber']/r['val2_ber']+(1-a)*ref['total_seconds']/r['total_seconds']
def best(c,a):return max(D[c],key=lambda r:(score(r,a),-r['total_seconds'],-r['total_iteration']))
def envelope(c,a):return np.max(np.array([score(r,a) for r in D[c]]),axis=0)
selected={c:best(c,.8) for c in ids};winner=max(ids,key=lambda c:score(selected[c],.8))
front=sorted([r for r in selected.values() if not any(s['total_seconds']<=r['total_seconds'] and s['val2_ber']<=r['val2_ber'] and (s['total_seconds']<r['total_seconds'] or s['val2_ber']<r['val2_ber']) for s in selected.values())],key=lambda r:r['total_seconds'])
GREY='#ADB5BD';NAVY='#D95319';GREEN='#0072BD';PURPLE='#EDB120';CYAN='#77AC30';AMBER='#7E2F8E'
alpha=np.linspace(0,1,1001);winners={float(a):max(ids,key=lambda c:envelope(c,a)) for a in [.2,.4,.6,.8,.9,1]}
highlights=['d8_w64','d6_w64','d4_w64','d9_w32']
COLORS=dict(zip(highlights,[GREEN,PURPLE,AMBER,CYAN]));MARKERS=dict(zip(highlights,['o','^','D','s']));STYLES=dict(zip(highlights,['-','--','-.',':']))
def label(c):return c.replace('d','').replace('_w','-')
def style(ax):
 ax.grid(True,which='major',color='#D5D8DC',linewidth=.5);ax.set_axisbelow(True);ax.tick_params(direction='in',length=3,width=.65)
def save(fig,name):
 for ext in ['pdf','svg','png']:fig.savefig(OUT/(name+'.'+ext),dpi=300,bbox_inches='tight',pad_inches=.03)
 plt.close(fig)
# Full candidate grid. Border is derived from data, never hard-coded.
fig,ax=plt.subplots(figsize=(3.5,1.9));matrix=np.array([[score(selected[f'd{d}_w{w}'],.8) for d in range(1,11)] for w in [8,16,32,64]])
# Blue--cyan--yellow anchors sampled from the PEBS heatmap in figs/overview.pdf.
cmap=LinearSegmentedColormap.from_list('pebs_overview',[
 '#4232CC','#4650F2','#2C88F3','#05BBBE','#2CC3A3','#F5DB28','#F8F913'])
vmax=max(20,np.ceil(matrix.max()/5)*5);im=ax.imshow(matrix,aspect='auto',cmap=cmap,vmin=0,vmax=vmax)
for i,w in enumerate([8,16,32,64]):
 for j,d in enumerate(range(1,11)):
  rgb=np.asarray(cmap(im.norm(matrix[i,j]))[:3])
  linear=np.where(rgb<=.04045,rgb/12.92,((rgb+.055)/1.055)**2.4)
  luminance=float(linear @ np.array([.2126,.7152,.0722]))
  ax.text(j,i,f'{matrix[i,j]:.1f}',ha='center',va='center',color='black' if luminance>.179 else 'white')
  if f'd{d}_w{w}'==winner:ax.add_patch(Rectangle((j-.5,i-.5),1,1,fill=False,ec='#1B2631',lw=1.6))
ax.set(xticks=range(10),xticklabels=range(1,11),yticks=range(4),yticklabels=[8,16,32,64],xlabel='Estimator depth',ylabel='Initial filter width')
ax.set_xticks(np.arange(-.5,10,1),minor=True);ax.set_yticks(np.arange(-.5,4,1),minor=True);ax.grid(which='minor',color='white',linewidth=.5);ax.tick_params(which='both',length=0)
cbar=fig.colorbar(im,ax=ax,fraction=.032,pad=.025);cbar.set_label(r'PEBS ($\alpha=0.8$)');cbar.ax.yaxis.set_major_locator(MaxNLocator(3));fig.subplots_adjust(left=.14,right=.88,bottom=.25,top=.96)
save(fig,'pebs_heatmap_40')
if '--heatmap-only' in sys.argv: raise SystemExit(0)
